/* Device-local demo backend. This permission boundary prevents accidental UI leaks;
   it is NOT server authentication. Never put real confidential data in this app. */
window.ConnextModel = (()=>{
  const config=window.CONNEXT_CONFIG;
  const fresh=()=>window.ConnextSeed();
  let state;
  function reload(){try{const value=JSON.parse(localStorage.getItem(config.storageKey));state=value?.version===1?value:fresh();}catch{state=fresh();}}
  reload();
  const clone=v=>JSON.parse(JSON.stringify(v));
  const days=date=>Math.max(0,Math.floor((Date.now()-new Date(date))/86400000));
  const uid=prefix=>`${prefix}-${Date.now()}-${Math.random().toString(36).slice(2,7)}`;
  function save(){try{localStorage.setItem(config.storageKey,JSON.stringify(state));}catch{window.dispatchEvent(new Event('connext-storage-error'));}window.dispatchEvent(new Event('connext-change'));}
  function permission(record,role){if(role==='student')return record.studentId==='aanya'&&record.sensitivity!=='restricted'?'full':'hidden';if(record.sensitivity!=='restricted')return 'full';if(record.restrictedTo?.includes(role))return 'full';return record.hideExistence?'hidden':'redacted';}
  function visible(record,role){const access=permission(record,role);if(access==='hidden')return null;const copy=clone(record);copy.access=access;if(copy.originalRequest&&copy.journeyId&&state.cases.some(c=>c.journeyId===copy.journeyId&&c.sensitivity==='restricted'&&!c.restrictedTo?.includes(role)))copy.originalRequest='Intake contains restricted support context. Contact Student Support for the shared operational brief.';if(access==='redacted'){delete copy.privateNote;delete copy.originalRequest;copy.summary=record.department==='wellbeing'?'Wellbeing support — details restricted':'Restricted department support';if('text' in copy)copy.text='Restricted to Counselling';if('brief' in copy)copy.brief='Context restricted to the receiving team.';}return copy;}
  function get(role='coordinator'){
    const result=clone(state);
    for(const key of ['cases','events','tasks','handoffs'])result[key]=state[key].map(r=>{const linked=r.caseId?state.cases.find(c=>c.id===r.caseId):null;return visible({...r,...(linked?{sensitivity:linked.sensitivity,restrictedTo:linked.restrictedTo,hideExistence:linked.hideExistence}:{})},role);}).filter(Boolean);
    result.records=state.records.filter(r=>role==='coordinator'||state.roles.find(x=>x.id===role)?.department===r.department).map(clone);
    if(role==='student'){result.students=result.students.filter(s=>s.id==='aanya');result.records=[];result.roles=clone(state.roles);}
    return result;
  }
  function flags(student,data){
    const cases=data.cases.filter(c=>c.studentId===student.id&&c.status!=='Resolved');const pending=data.handoffs.filter(h=>h.studentId===student.id&&h.status==='Pending');const depts=[...new Set(cases.map(c=>c.department))];const f=[];
    pending.filter(h=>days(h.createdAt)>config.referralDays).forEach(h=>f.push({type:'referral',label:'Referral overdue',reason:`Referral pending ${days(h.createdAt)} days; the receiving team has not accepted it.`,weight:config.weights.referral}));
    cases.filter(c=>c.appointmentRequestedAt&&!c.appointmentBooked&&days(c.appointmentRequestedAt)>config.appointmentDays).forEach(c=>f.push({type:'appointment',label:'Appointment waiting',reason:`First appointment requested ${days(c.appointmentRequestedAt)} days ago and still unbooked.`,weight:config.weights.appointment}));
    if(depts.length>=config.departmentCount)f.push({type:'multi',label:student.id==='ishita'?'Connected signals':'Multiple departments',reason:`${depts.length} departments are supporting this student. ${student.id==='ishita'?'A delayed scholarship, missed exam and hostel check-in need a shared response.':'A shared plan will prevent repeated explanations.'}`,weight:config.weights.multi});
    if(!student.hold&&cases.some(c=>c.sensitivity==='restricted')&&data.events.some(e=>e.studentId===student.id&&e.type==='reminder'))f.push({type:'reminder',label:'Conflicting reminder',reason:'A fee reminder was sent while a sensitive support case was open. Consider pausing reminders.',weight:config.weights.reminder});
    if(cases.some(c=>c.approved&&!c.shared))f.push({type:'unshared',label:'Missing handoff',reason:'An approved accommodation has not reached the Exams team.',weight:config.weights.unshared});
    const wait=Math.max(0,...cases.map(c=>days(c.openedAt)));const score=f.length?f.reduce((sum,x)=>sum+x.weight,0)+Math.min(wait,35)+depts.length:0;
    return {flags:f,score,wait,departments:depts,cases,level:score>=70?'Urgent':score>=40?'High':score>0?'Moderate':'On track'};
  }
  function append(studentId,department,type,text,role,extra={}){state.events.push({id:uid('ev'),studentId,department,type,text,actor:state.roles.find(r=>r.id===role)?.user||'Demo staff',at:new Date().toISOString(),...extra});}
  function canEdit(record,role){return role==='coordinator'||state.roles.find(r=>r.id===role)?.department===record.department;}
  function assert(ok,message='This action belongs to another department.'){if(!ok)throw new Error(message);}
  function mutate(action,payload,role){
    assert(role!=='student','Student demo is read-only.');
    if(action==='status'){const c=state.cases.find(c=>c.id===payload.id);assert(c&&permission(c,role)!=='hidden'&&canEdit(c,role));assert(['Pending','In progress','Waiting on student','Resolved'].includes(payload.status));c.status=payload.status;append(c.studentId,c.department,'status',`${c.id} changed to ${c.status}.`,role,{caseId:c.id});}
    if(action==='task'){const t=state.tasks.find(t=>t.id===payload.id);assert(t&&canEdit(t,role));t.done=!!payload.done;append(t.studentId,t.department,'task',`${t.done?'Completed':'Reopened'} task: ${t.title}`,role,{caseId:t.caseId});}
    if(action==='note'){assert(payload.text?.trim(),'Enter a note.');const dept=payload.department||state.roles.find(r=>r.id===role).department;assert(role==='coordinator'||state.roles.find(r=>r.id===role).department===dept);const restricted=payload.restricted===true;assert(!restricted||['counsellor','grievance'].includes(role),'Only authorised departments can add restricted notes.');append(payload.studentId,dept,'note',payload.text.trim(),role,restricted?{sensitivity:'restricted',restrictedTo:[role],hideExistence:role==='grievance'}:{});}
    if(action==='addTask'){assert(payload.title?.trim(),'Enter a task.');assert(role==='coordinator'||state.roles.find(r=>r.id===role).department===payload.department);state.tasks.push({id:uid('t'),studentId:payload.studentId,title:payload.title.trim(),department:payload.department,due:new Date(payload.due+'T12:00:00').toISOString(),done:false});append(payload.studentId,payload.department,'task',`Created task: ${payload.title.trim()}`,role);}
    if(action==='hold'){assert(['coordinator','fees'].includes(role));const s=state.students.find(s=>s.id===payload.studentId);s.hold=!s.hold;append(s.id,'fees','hold',s.hold?'Coordinated hold enabled. Pause reminders and contact Student Support.':'Coordinated hold released. Fee reminders may resume.',role);}
    if(action==='handoff'){assert(payload.from!==payload.to,'Choose a different receiving department.');assert(role==='coordinator'||state.roles.find(r=>r.id===role).department===payload.from);const h={id:uid('HO'),studentId:payload.studentId,from:payload.from,to:payload.to,brief:payload.brief,status:'Pending',createdAt:new Date().toISOString(),caseId:payload.caseId};state.handoffs.push(h);append(h.studentId,h.from,'handoff',`Handoff sent to ${state.departments.find(d=>d.id===h.to).name}; awaiting acceptance.`,role,{caseId:h.caseId});}
    if(action==='accept'){const h=state.handoffs.find(h=>h.id===payload.id);assert(h&&h.status==='Pending');assert(role==='coordinator'||state.roles.find(r=>r.id===role).department===h.to,'Switch to the receiving department to accept this handoff.');h.status='Accepted';h.acceptedAt=new Date().toISOString();let c=state.cases.find(c=>c.id===h.caseId);if(c){c.status='In progress';if(c.approved)c.shared=true;}if(!state.cases.some(c=>c.studentId===h.studentId&&c.department===h.to)){state.cases.push({id:uid('CNX'),studentId:h.studentId,department:h.to,summary:'Accepted coordinated support handoff',openedAt:new Date().toISOString(),status:'In progress',owner:state.departments.find(d=>d.id===h.to).initials,sensitivity:h.to==='wellbeing'?'restricted':'normal',...(h.to==='wellbeing'?{restrictedTo:['counsellor']}:{})});}append(h.studentId,h.to,'handoff','Handoff accepted. Receiving department now owns the next action.',role,{caseId:h.caseId});}
    if(action==='appointment'){const c=state.cases.find(c=>c.id===payload.id);assert(c&&canEdit(c,role));c.appointmentBooked=true;c.appointmentDate=payload.date;c.status='In progress';append(c.studentId,c.department,'appointment',`First appointment booked for ${new Date(payload.date).toLocaleString('en-IN',{dateStyle:'medium',timeStyle:'short'})}.`,role,{caseId:c.id});}
    if(action==='link'){assert(role==='coordinator');const cs=state.cases.filter(c=>payload.ids.includes(c.id));assert(cs.length===2&&cs[0].studentId===cs[1].studentId);if(!state.links.some(l=>l.ids.includes(cs[0].id)&&l.ids.includes(cs[1].id)))state.links.push({id:uid('link'),ids:payload.ids});append(cs[0].studentId,'affairs','linked','Related medical-leave cases linked. Both department histories are preserved.',role);}
    if(action==='intake'){assert(payload.text?.trim(),'Describe the support request.');const student=state.students.find(s=>s.id===payload.studentId);assert(student);const departments=payload.departments.filter(d=>state.departments.some(x=>x.id===d));assert(departments.length>0);const journeyId=uid('JNY');const created=[];for(const department of departments){const id=uid('CNX');const restricted=department==='wellbeing';state.cases.push({id,journeyId,studentId:student.id,department,summary:payload.summary,originalRequest:payload.text,openedAt:new Date().toISOString(),status:'Pending',owner:state.departments.find(d=>d.id===department).initials,sensitivity:restricted?'restricted':'normal',...(restricted?{restrictedTo:['counsellor']}:{} )});created.push(id);state.tasks.push({id:uid('t'),studentId:student.id,caseId:id,department,title:`Review request and contact ${student.name.split(' ')[0]}`,due:new Date(Date.now()+2*86400000).toISOString(),done:false});append(student.id,department,'created',`Support request routed to ${state.departments.find(d=>d.id===department).short}.`,role,{caseId:id});}return save(),created;}
    save();
  }
  function intake(text){const t=text.toLowerCase();const departments=[];if(/fee|money|pay|financial|afford/.test(t))departments.push('fees');if(/scholarship|fund|aid/.test(t))departments.push('scholarships');if(/class|attend|exam|academic|leave/.test(t))departments.push('academics');if(/hostel|room|accommodation|residen/.test(t))departments.push('hostel');if(/counsel|stress|mood|anxious|worried|wellbeing/.test(t))departments.push('wellbeing');if(/health|medical/.test(t))departments.push('health');if(/accessib|adjustment|disab/.test(t))departments.push('access');if(!departments.length)departments.push('affairs');return {departments,summary:'Support requested from '+departments.map(id=>state.departments.find(d=>d.id===id).short).join(', ')+'. Coordinate a shared response and confirm the next step.',priority:departments.length>=3?'High':'Moderate'};}
  function reset(){state=fresh();save();}
  return {get,flags,days,permission,mutate,intake,reset,reload,canEdit};
})();
